        assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
            assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
                // Check what changed between pre and post states:
                // - producer changed: pre.producer = Idle(tail), post.producer = Producing(tail)
                // - storage changed: post.storage = pre.storage.remove(tail)
                // - all other fields remain the same

                // Determine if index i is checked out in post state
                if post.is_checked_out(i) {
                    // In post state, index i is checked out
                    // This means either:
                    // 1. post.producer = Producing(i), which means i = tail, or
                    // 2. post.consumer = Consuming(i)

                    if i == tail {
                        // Index i is tail, which is now checked out by producer
                        assert(post.producer == ProducerState::Producing(i));
                        // When checked out, there should be no permission in storage for i
                        assert(!post.storage.dom().contains(i));
                        // This satisfies valid_storage_at_idx
                        assert(post.valid_storage_at_idx(i));
                    } else {
                        // Index i is checked out by consumer (unchanged from pre)
                        assert(post.consumer == ConsumerState::Consuming(i));
                        assert(pre.consumer == ConsumerState::Consuming(i));
                        assert(pre.is_checked_out(i));
                        // Since it was checked out in pre, it wasn't in pre.storage
                        assert(!pre.storage.dom().contains(i));
                        // Since the only change to storage was removing tail (which is not i),
                        // it's also not in post.storage
                        assert(!post.storage.dom().contains(i));
                        // This satisfies valid_storage_at_idx
                        assert(post.valid_storage_at_idx(i));
                    }
                } else {
                    // In post state, index i is NOT checked out
                    assert(!post.is_checked_out(i));
                    // This means:
                    // 1. post.producer != Producing(i), so either post.producer = Idle(_) or i != tail
                    // 2. post.consumer != Consuming(i)

                    // Since post.consumer = pre.consumer, we have pre.consumer != Consuming(i)
                    // Since post.producer = Producing(tail), we have Producing(tail) != Producing(i), so i != tail
                    // Or post.producer = Producing(tail) and i != tail

                    // Since i is not checked out in post, there must be a permission in post.storage for i
                    assert(post.storage.dom().contains(i));

                    // Since i is not checked out in pre (because i != tail and pre.consumer != Consuming(i)), 
                    // there was also a permission in pre.storage for i
                    assert(pre.storage.dom().contains(i));

                    // The permission for i in post should be the same as in pre 
                    // (since only permission for tail was removed)
                    assert(post.storage.index(i) == pre.storage.index(i));

                    // Verify all conditions of valid_storage_at_idx:
                    // 1. Permission is stored (shown above)
                    // 2. Permission id matches backing cell id
                    assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
                    //    (This follows because pre had this property and nothing changed)
                    assert(pre.storage.index(i).id() == pre.backing_cells.index(i as int));
                    assert(post.backing_cells == pre.backing_cells);
                    // 3. Permission init/uninit status matches in_active_range status
                    assert((post.storage.index(i).is_init() == post.in_active_range(i)) 
                           == (pre.storage.index(i).is_init() == pre.in_active_range(i)));
                    //    (This follows because storage and active range didn't change)
                    assert(post.in_active_range(i) == pre.in_active_range(i));

                    // Since pre satisfied valid_storage_at_idx(i) and all the conditions are the same in post,
                    // post also satisfies valid_storage_at_idx(i)
                    assert(pre.valid_storage_at_idx(i));
                    assert(post.valid_storage_at_idx(i));
                }
            }
        }
    }
    #[inductive(produce_end)]
    fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        admit()
    }
    #[inductive(consume_start)]
    fn consume_start_inductive(pre: Self, post: Self) {
        admit()
    }
    #[inductive(consume_end)]
    fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        admit()
